<?php
function handle_shop_option_action(string $action): bool {
    switch($action){
        case 'catalog_module_save':require_admin();$id=save_catalog_module((int)($_POST['module_id']??0),$_POST);flash('Zentrales Modul gespeichert. Verknüpfte Pakete verwenden die aktuellen Moduldefinitionen; bestehende Bestellungen behalten ihre gespeicherte Ausstattung.');redirect('/admin/module?id='.$id);
        case 'catalog_module_templates':require_admin();$category=(string)($_POST['category']??'');if(!in_array($category,['hosting','server'],true))throw new RuntimeException('Ungültige Modulkategorie.');db()->beginTransaction();try{seed_catalog_modules($category);db()->commit();}catch(Throwable $e){db()->rollBack();throw $e;}flash('Zentrale Modulvorlagen als inaktive Entwürfe angelegt. Preise und Auswahloptionen festlegen und einzeln freigeben.');redirect('/admin/module?kategorie='.$category);
        case 'hosting_capabilities_refresh':require_admin();hosting_capabilities(true);flash('PHP-Betriebsarten und Versionen wurden erneut von ISPConfig eingelesen.');redirect('/admin/module?kategorie=hosting');
        case 'document_save':require_admin();$id=save_shop_document((int)($_POST['id']??0),$_POST,$_FILES['pdf']??null);flash('Dokumententwurf gespeichert. Die veröffentlichte Fassung bleibt bis zur Freigabe bestehen.');redirect('/admin/dokumente?id='.$id);
        case 'document_publish':$admin=require_admin();$v=publish_shop_document((int)($_POST['id']??0),(int)$admin['id'],isset($_POST['use_checkout']));flash('Fassung '.$v['version_no'].' veröffentlicht. Ältere Bestellungen behalten ihre gespeicherten Dokumentfassungen.');redirect('/admin/dokumente?id='.$v['document_id']);
        case 'product_module_save':require_admin();$product=(int)($_POST['product_id']??0);$id=save_product_module((int)($_POST['module_id']??0),$product,$_POST);flash('Modul und Preis gespeichert.');redirect('/admin/produkte?id='.$product.'&modul='.$id.'#zusatzmodule');
        case 'product_module_templates':require_admin();$product=(int)($_POST['product_id']??0);seed_product_modules($product);flash('Modulvorlagen als inaktive Entwürfe angelegt. Preise, Mengen und Wirkung einstellen und einzeln aktivieren.');redirect('/admin/produkte?id='.$product.'#zusatzmodule');
        case 'admin_payment_confirm':$admin=require_admin();rate_limit('admin_payment_confirm',20,3600);$id=(int)($_POST['order_id']??0);admin_confirm_payment($id,$_POST,(int)$admin['id']);flash('Zahlungsbestätigung gespeichert. Testzahlungen bleiben als Test erkennbar.');redirect('/admin/bestellungen?id='.$id);
        case 'hosting_sync':$customer=require_user();$id=(int)($_POST['service_id']??0);$service=bound_service($id,(int)$customer['id'],true);rate_limit('hosting_sync',10,900);$count=sync_hosting_accesses($service);$_SESSION['hosting_synced'][$id]=time();flash($count.' vorhandene Zugänge übernommen. Bestehende Passwörter können bei Bedarf neu gesetzt werden.');redirect('/konto/verwalten?id='.$id);
        case 'hosting_panel_password':$customer=require_user();$id=(int)($_POST['service_id']??0);$service=bound_service($id,(int)$customer['id'],true);rate_limit('hosting_panel_password',10,3600);set_hosting_panel_password($service,(string)($_POST['new_password']??''));flash('Dein ISPConfig-Passwort wurde geändert und verschlüsselt gespeichert.');redirect('/konto/verwalten?id='.$id.'#ispconfig-zugang');
        case 'hosting_panel_credentials':$customer=require_user();$service=bound_service((int)($_POST['service_id']??0),(int)$customer['id'],true);rate_limit('credentials_view',30,900);$GLOBALS['revealed_hosting_panel']=reveal_hosting_panel_login($service);header('Cache-Control: no-store');return true;
        case 'hosting_mail_settings':$customer=require_user();$id=(int)($_POST['service_id']??0);$service=bound_service($id,(int)$customer['id'],true);if($service['provider']!=='ispconfig')throw new RuntimeException('Ungültiger Anbieter.');rate_limit('hosting_write',20,3600);hosting_mail_settings($service,(int)($_POST['child_id']??0),$_POST);unset($_SESSION['hosting_synced'][$id]);flash('Die Postfacheinstellungen wurden an ISPConfig übergeben.');redirect('/konto/verwalten?id='.$id.'#postfaecher');
        case 'hosting_mail_spam_settings':$customer=require_user();$id=(int)($_POST['service_id']??0);$service=bound_service($id,(int)$customer['id'],true);rate_limit('hosting_write',20,3600);hosting_mail_spam_settings($service,(int)($_POST['child_id']??0),$_POST);flash('Die Spamfilter-Einstellungen wurden an ISPConfig übergeben.');redirect('/konto/verwalten?id='.$id.'#postfaecher');
        case 'hosting_child_credentials':$customer=require_user();$service=bound_service((int)($_POST['service_id']??0),(int)$customer['id'],true);if($service['provider']!=='ispconfig')throw new RuntimeException('Ungültiger Anbieter.');rate_limit('credentials_view',30,900);$child=(int)($_POST['child_id']??0);$GLOBALS['revealed_hosting_children'][$child]=reveal_child_credentials($service,$child);header('Cache-Control: no-store');return true;
        case 'hosting_cron_create':case 'hosting_cron_delete':$customer=require_user();$id=(int)($_POST['service_id']??0);$service=bound_service($id,(int)$customer['id'],true);if($service['provider']!=='ispconfig')throw new RuntimeException('Ungültiger Anbieter.');rate_limit('hosting_cron',20,3600);if($action==='hosting_cron_create')hosting_cron_create($service,$_POST);else hosting_cron_delete($service,(int)($_POST['child_id']??0));flash('Cronjob bei ISPConfig aktualisiert.');redirect('/konto/verwalten?id='.$id);
        default:return false;
    }
}
